
import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import squizInfoMock from '@ntgovernment/squiz-factory/plugins/squizInfo.mock';
import comp from './main.js';

const squiz = squizStoryRenderer(comp.main);

/**
 * Note: info is optional
 *       we only need this if ever a component needs to use
 *       things of the squiz component fn optional 2nd argument info
 *       it will allow is to mock so the story can work.
 */
const info = squizInfoMock();

export default {
  title: 'dxp/My Component',
};

const defaultArgs = {
  text: 'Hello World!',
};

const defaultHtml = await squiz.markup(defaultArgs);

export const Default = {
  render: (args) => squiz(args),
  args: defaultArgs,
  argTypes: {
    text: { control: 'text' },
    variant: { control: 'text' },
  },
  parameters: {
    docs: { source: { code: defaultHtml, language: 'html', type: 'code' } },
  },
};

const specialArgs = { text: "I'm Special!", variant: 'special' };
const specialHtml = await squiz.markup(specialArgs);

export const Special = {
  render: () => squiz(specialArgs),
  parameters: {
    docs: { source: { code: specialHtml, language: 'html', type: 'code' } },
  },
};
