/**
 * My Component - Main rendering function
 * Renders text content with optional variant styling
 */

export default {
  main: async ({ text = 'Hello World!', variant = 'default' } = {}) => {
    const variantClass = variant && variant !== 'default' ? ` my-component--${variant}` : '';

    return /*html*/`
      <div class="my-component${variantClass}">
        <div class="my-component__text">
          ${text}
        </div>
      </div>
    `;
  }
}
